INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','reflexive-reciprocal','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"reflexive-reciprocal","title":"Reflexive and reciprocal pronouns","level":"B1","order":53,"summary":"Distinguish doing something to yourself, doing it alone and doing it to one another.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["The same participant twice","Emphasis and independence","Reciprocal actions","Use a reflexive only when its role needs one"],"rules":[{"title":"The same participant twice","explanation":"A reflexive pronoun can be used when the subject and object refer to the same person or thing. Its form matches the subject: myself, yourself, himself, herself, itself, ourselves, yourselves, themselves.","pattern":"She introduced **herself**.","commonMistakes":["Her and herself are not interchangeable: her normally refers to someone other than the subject in this example."],"examples":["“She prepared the visitor guide by **herself**.” Choose the matching reflexive.","“She restored the old portrait by **herself**.” Choose the matching reflexive."],"skill":"form"},{"title":"Emphasis and independence","explanation":"A reflexive can emphasise that the subject personally did the action. **By + reflexive** usually means alone or without help. **For + reflexive** means for one’s own benefit. These meanings are related but not identical.","pattern":"I made it **myself**. / I did it **by myself**.","commonMistakes":["By myself says without company or help; for myself says who benefits."],"examples":["“We prepared the visitor guide by **ourselves**.”","“We restored the old portrait by **ourselves**.”"],"skill":"meaning"},{"title":"Reciprocal actions","explanation":"Each other and one another express a reciprocal relationship: A acts on B and B acts on A. They are not equivalent to themselves, where each participant’s action returns to that same participant.","pattern":"They introduced **each other**.","commonMistakes":["They looked at themselves means each looked at their own reflection; each other means they looked across at one another."],"examples":["“The two assistants helped each other to prepare the visitor guide.” What does “each other” show? → **Each assistant helped the other assistant.**","“The two assistants helped each other to restore the old portrait.” What does “each other” show? → **Each assistant helped the other assistant.**"],"skill":"contrast"},{"title":"Use a reflexive only when its role needs one","explanation":"Ordinary English often omits reflexives with routine personal-care verbs: she washed and dressed. A reflexive is not a generally more polite substitute for me or I. In a coordinated subject, use I in formal standard prose.","pattern":"Please contact Sam or **me**.","commonMistakes":["Please contact myself is not the ordinary formal choice when no matching subject creates a reflexive relationship."],"examples":["“The supervisor asked Sam and **me** to prepare the visitor guide.” Choose the standard object pronoun for the speaker.","“The supervisor asked Sam and **me** to restore the old portrait.” Choose the standard object pronoun for the speaker."],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reflexive"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"46f2d443-68d0-5221-a5d9-85fc78a27aa5","topicSlug":"reflexive-reciprocal","level":"B1","prompt":"“She prepared the visitor guide by ____.” Choose the matching reflexive.","choices":[{"id":"A","text":"himself"},{"id":"B","text":"themselves"},{"id":"C","text":"her"},{"id":"D","text":"herself"}],"answerId":"D","hint":"Match the reflexive to **she**, and recognise **by herself**.","explanation":"**Herself** matches the feminine singular subject she; by herself means without help or company.","keywords":["singular-reflexive"],"skill":"singular-reflexive","contextKey":"reflexive-reciprocal-1","fingerprint":"1a4d5be27676b9703abceebefc29a3c181b2b2ee6da61439dc3a47dbfc4b6a17","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reflexive"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Match the reflexive to **she**, and recognise **by herself**.","**Herself** matches the feminine singular subject she; by herself means without help or company.","Choose **herself**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Himself does not match she.","B":"Themselves does not match the explicitly supplied she in this exercise.","C":"After by in the alone meaning, use the reflexive herself, not object her.","D":"**Herself** matches the feminine singular subject she; by herself means without help or company."}}},{"id":"25a5e84c-083f-5b64-af3d-79b92c117840","topicSlug":"reflexive-reciprocal","level":"B1","prompt":"“We prepared the visitor guide by ____.”","choices":[{"id":"A","text":"us"},{"id":"B","text":"ourselves"},{"id":"C","text":"myself"},{"id":"D","text":"ourself"}],"answerId":"B","hint":"We requires the plural first-person reflexive **ourselves**.","explanation":"The plural first-person subject we takes **ourselves**.","keywords":["plural-reflexive"],"skill":"plural-reflexive","contextKey":"reflexive-reciprocal-1","fingerprint":"3eaf4a7c52d2aeb7b760cb74f00b038e2bfd79f1d484bc9a624b423c2ff9aec3","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reflexive"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["We requires the plural first-person reflexive **ourselves**.","The plural first-person subject we takes **ourselves**.","Choose **ourselves**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The alone/without-help expression needs a reflexive after by.","B":"The plural first-person subject we takes **ourselves**.","C":"Myself is singular and matches I, not we.","D":"The ordinary plural reflexive for we is ourselves."}}},{"id":"b8ff5781-142b-51d6-a071-0cfcf1ef74f2","topicSlug":"reflexive-reciprocal","level":"B1","prompt":"“The two assistants helped each other to prepare the visitor guide.” What does “each other” show?","choices":[{"id":"A","text":"Each assistant helped only themselves."},{"id":"B","text":"Only one assistant received help."},{"id":"C","text":"Neither assistant received help."},{"id":"D","text":"Each assistant helped the other assistant."}],"answerId":"D","hint":"A reciprocal action goes **from A to B and from B to A**.","explanation":"**Each other** expresses a reciprocal action between the two assistants.","keywords":["reciprocal-meaning"],"skill":"reciprocal-meaning","contextKey":"reflexive-reciprocal-1","fingerprint":"98b63a710e90834c04cae430656ce105b44965ac8c0c1cd7ef7921e6bbc95698","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reflexive"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A reciprocal action goes **from A to B and from B to A**.","**Each other** expresses a reciprocal action between the two assistants.","Choose **Each assistant helped the other assistant.**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That would be reflexive, not reciprocal.","B":"The stated reciprocal relationship goes both ways.","C":"This contradicts helped each other.","D":"**Each other** expresses a reciprocal action between the two assistants."}}},{"id":"f725179d-fec9-5fd3-a5bc-cd1bc8017bfc","topicSlug":"reflexive-reciprocal","level":"B1","prompt":"“The supervisor asked Sam and ____ to prepare the visitor guide.” Choose the standard object pronoun for the speaker.","choices":[{"id":"A","text":"mine"},{"id":"B","text":"me"},{"id":"C","text":"I"},{"id":"D","text":"myself"}],"answerId":"B","hint":"Test the role without the other name: **asked me**.","explanation":"Sam and **me** is the object of asked; removing Sam and leaves asked me.","keywords":["ordinary-object-pronoun"],"skill":"ordinary-object-pronoun","contextKey":"reflexive-reciprocal-1","fingerprint":"bc9360f310c38017add1790e17cfefa7ef989572ca05a87db2d019ff59cd9d14","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-reflexive"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Test the role without the other name: **asked me**.","Sam and **me** is the object of asked; removing Sam and leaves asked me.","Choose **me**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Mine is possessive and cannot be the person object here.","B":"Sam and **me** is the object of asked; removing Sam and leaves asked me.","C":"I is a subject pronoun, but the phrase is the object of asked.","D":"The subject is the supervisor, so myself has no matching subject for an ordinary reflexive use."}}},{"id":"03e7e86f-2691-5ef6-a324-35db6f7a9965","topicSlug":"reflexive-reciprocal","level":"B1","prompt":"“She restored the old portrait by ____.” Choose the matching reflexive.","choices":[{"id":"A","text":"themselves"},{"id":"B","text":"her"},{"id":"C","text":"herself"},{"id":"D","text":"himself"}],"answerId":"C","hint":"Match the reflexive to **she**, and recognise **by herself**.","explanation":"**Herself** matches the feminine singular subject she; by herself means without help or company.","keywords":["singular-reflexive"],"skill":"singular-reflexive","contextKey":"reflexive-reciprocal-2","fingerprint":"31e3dd5e89836b9b8272d9475b015d80ab21